const files = {};
for (const [id, body] of Object.entries(BODIES)) {
  const f = FILE_OF(id);
  files[f] = files[f] || fs.readFileSync(path.join(ROOT, f), "utf8");
  files[f] = setField(files[f], id, "body", body);
  console.log(id, body.replace(/\s+/g, "").length);
}
for (const [f, src] of Object.entries(files)) fs.writeFileSync(path.join(ROOT, f), src);
